import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor tenant isolation", () => {
  test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs }) => {
    // Arrange: a vendor that belongs to Globex Procurement
    const other = await apiAs("otherTenant");
    const created = await other.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "software",
        contact_email: "accounts@globex-vendor.com",
      },
    });
    const createdBody = await created.text();
    expect(created.status(), createdBody).toBe(201);
    const vendor = JSON.parse(createdBody) as { id: string };

    // Act: Northwind member requests that vendor by id
    const member = await apiAs("member");
    const res = await member.get(`/api/vendors/${vendor.id}`);
    const body = await res.text();

    // Assert
    expect(res.status(), body).toBe(404);
    expect(JSON.parse(body).error.code, body).toBe("vendor_not_found");
  });
});
